# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HZ. PEYGAMBER\'İN GENÇLİK YILLARINDAKİ ERDEMLERİ VE FAALİYETLERİ</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. ÇALIŞMA VE İŞ AHLAKI</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Ebû Talip\'in aile bütçesine</text>\n  <text x="48" y="114" font-size="10.5" fill="#475569">katkı için çobanlık yapması</text>\n  <text x="38" y="138" font-size="11" fill="#334155">• Şam ve Yemen kervanlarıyla</text>\n  <text x="48" y="154" font-size="10.5" fill="#475569">dürüst ticaret yürütmesi</text>\n  <text x="38" y="178" font-size="11" font-weight="bold" fill="#1d4ed8">• Unvanı: Muhammedü\'l-Emin</text>\n  <text x="48" y="194" font-size="10.5" fill="#475569">(Doğru sözlü ve güvenilir)</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">2. BARIŞ VE ADALET ÇABASI</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Ficar Savaşlarında kan</text>\n  <text x="270" y="114" font-size="10.5" fill="#475569">dökülmesine karşı durması</text>\n  <text x="260" y="138" font-size="11" fill="#334155">• Hilfü\'l-Fudûl (Erdemliler</text>\n  <text x="270" y="154" font-size="10.5" fill="#475569">Topluluğu) içinde yer alması</text>\n  <text x="260" y="178" font-size="11" font-weight="bold" fill="#15803d">• İlkesi: Mazlumun hakkını</text>\n  <text x="270" y="194" font-size="10.5" fill="#475569">zalimden alıncaya dek savunmak</text>\n  <rect x="469" y="48" width="205" height="190" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="571" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">3. AİLE VE TOPLUMSAL UZLAŞI</text>\n  <text x="482" y="98" font-size="11" fill="#334155">• 25 yaşında Hz. Hatice ile</text>\n  <text x="492" y="114" font-size="10.5" fill="#475569">örnek bir yuva kurması</text>\n  <text x="482" y="138" font-size="11" fill="#334155">• 35 yaşında Kâbe onarımında</text>\n  <text x="492" y="154" font-size="10.5" fill="#475569">Hacerü\'l-Esved hakemliği</text>\n  <text x="482" y="178" font-size="11" font-weight="bold" fill="#a16207">• Sonuç: Kabileler arası kanlı</text>\n  <text x="492" y="194" font-size="10.5" fill="#475569">bir çatışmayı bilgelikle önlemesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HİLFÜ\'L-FUDÛL (ERDEMLİLER TOPLULUĞU — MİLADİ 590)</text>\n  <rect x="25" y="50" width="195" height="185" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="122" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9f1239">KURULUŞ NEDENİ</text>\n  <text x="38" y="100" font-size="11" fill="#334155">• Ficar Savaşları sonrası Mekke\'de</text>\n  <text x="48" y="116" font-size="10.5" fill="#475569">otorite ve güven boşluğu</text>\n  <text x="38" y="140" font-size="11" fill="#334155">• Yemenli (Zebîdli) bir tüccarın</text>\n  <text x="48" y="156" font-size="10.5" fill="#475569">Âs b. Vâil tarafından</text>\n  <text x="48" y="172" font-size="10.5" fill="#475569">hakkının gasp edilmesi</text>\n  <text x="230" y="145" font-size="22" font-weight="bold" fill="#0f172a">➔</text>\n  <rect x="252" y="50" width="195" height="185" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="349" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TOPLANTI VE İLKELER</text>\n  <text x="265" y="100" font-size="11" fill="#334155">• Öncü: Zübeyr b. Abdülmuttalip</text>\n  <text x="265" y="122" font-size="11" fill="#334155">• Mekân: Abdullah b. Cüd\'ân\'ın evi</text>\n  <text x="265" y="146" font-size="11" font-weight="bold" fill="#1d4ed8">• Yemin Maddeleri:</text>\n  <text x="275" y="164" font-size="10.5" fill="#475569">1. Zulme rıza göstermemek</text>\n  <text x="275" y="180" font-size="10.5" fill="#475569">2. Mazlumun hakkını geri almak</text>\n  <text x="457" y="145" font-size="22" font-weight="bold" fill="#0f172a">➔</text>\n  <rect x="480" y="50" width="195" height="185" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="577" y="74" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TARİHÎ ÖNEMİ</text>\n  <text x="493" y="100" font-size="11" fill="#334155">• Kabile asabiyeti yerine hak ve</text>\n  <text x="503" y="116" font-size="10.5" fill="#475569">adaleti üstün tutmuştur.</text>\n  <text x="493" y="140" font-size="11" fill="#334155">• Hz. Peygamber 20 yaşında aktif</text>\n  <text x="503" y="156" font-size="10.5" fill="#475569">üye olarak katılmıştır.</text>\n  <text x="493" y="180" font-size="10.5" font-weight="bold" fill="#15803d">&quot;İslam\'da da çağrılsam yine</text>\n  <text x="493" y="196" font-size="10.5" font-weight="bold" fill="#15803d">icabet ederim.&quot; (Hadis-i Şerif)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KÂBE HAKEMLİĞİ OLAYI VE BARIŞÇIL ÇÖZÜM MODELİ (MİLADİ 605)</text>\n  <rect x="25" y="48" width="205" height="190" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="127" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">1. KRİZİN ÇIKIŞI</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Kâbe\'nin sel sonrası onarımı</text>\n  <text x="38" y="120" font-size="11" fill="#334155">• Hacerü\'l-Esved\'i yerine koyma</text>\n  <text x="48" y="136" font-size="10.5" fill="#475569">şerefi için kabile rekabeti</text>\n  <text x="38" y="160" font-size="11" font-weight="bold" fill="#b91c1c">• Tehlike: Kureyş kolları arasında</text>\n  <text x="48" y="176" font-size="10.5" fill="#475569">kanlı iç savaş yemini</text>\n  <rect x="247" y="48" width="205" height="190" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="349" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. HAKEM SEÇİMİ</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Ebû Ümeyye\'nin önerisi: Benî</text>\n  <text x="270" y="114" font-size="10.5" fill="#475569">Şeybe kapısından ilk giren kişi</text>\n  <text x="260" y="138" font-size="11" fill="#334155">• Hz. Muhammed\'in (35 yaşında)</text>\n  <text x="270" y="154" font-size="10.5" fill="#475569">Mescid-i Harâm\'a girişi</text>\n  <text x="260" y="178" font-size="11" font-weight="bold" fill="#1d4ed8">• Tepki: &quot;Bu el-Emîn\'dir, onun</text>\n  <text x="270" y="194" font-size="10.5" fill="#1d4ed8">vereceği hükme razıyız!&quot;</text>\n  <rect x="469" y="48" width="205" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="571" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">3. BİLGECE ÇÖZÜM</text>\n  <text x="482" y="98" font-size="11" fill="#334155">• Yere bir örtü (ridâ) serilmesi</text>\n  <text x="482" y="120" font-size="11" fill="#334155">• Her kabile reisinin örtünün bir</text>\n  <text x="492" y="136" font-size="10.5" fill="#475569">ucundan tutarak taşı kaldırması</text>\n  <text x="482" y="160" font-size="11" font-weight="bold" fill="#15803d">• Sonuç: Tüm kabileler onore</text>\n  <text x="492" y="176" font-size="10.5" fill="#475569">edilmiş, toplumsal barış</text>\n  <text x="492" y="192" font-size="10.5" fill="#475569">ve adalet korunmuştur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
